import datetimeprint()class Product:    def __init__(self, name_prod, cal):        self.name = name_prod        self.cal = cal    def return_cal(self):        return self.calclass MenuItem:    def __init__(self, name, price, calorie, in_dish):        self.name = name        self.price = price        self.calorie = calorie        self.in_dish = in_dishclass Order:    def __init__(self, dish=[], price=0, client=None, cal=0):        self.dish = dish        self.price = price        self.date = datetime.datetime.now().date()        self.client = client        self.cal = cal    def add_item(self, item):        self.dish.append(item.name)        self.price += item.price        self.cal += item.calorie    def total_price(self):        return self.priceclass Customer:    def __init__(self, name):        self.name = name        self.added_at = datetime.datetime.now()chicken = Product("Курица", 300)chease = Product("Сыр", 50)souse = Product("Соус", 200)sux = Product('Сухарики', 30)tomato = Product('Помидоры Чери', 20)# ------------------------------------------testo = Product('Тесто', 20)meat = Product('Колбаса', 140)# ================================================chesar = MenuItem('Салат Цезарь',                  400,                  sum([chicken.cal, chease.cal, souse.cal, sux.cal, tomato.cal]),                  [[chicken.name, chicken.cal], [chease.name, chease.cal], [souse.name, souse.cal],                   [sux.name, sux.cal], [tomato.name, tomato.cal]])# ------------------------------------------pizza = MenuItem(    'Пицца',    600,    sum([testo.cal, chease.cal, chicken.cal, meat.cal, tomato.cal, souse.cal]),    [[testo.name, testo.cal], [chease.name, chease.cal], [chicken.name, chicken.cal], [meat.name, meat.cal],     [tomato.name, tomato.cal], [souse.name, souse.cal]])# ================================================customer1 = Customer('Иван')# ================================================order = Order(client=customer1.name)order.add_item(pizza)order.add_item(chesar)name_dish = {    pizza.name: pizza,    chesar.name: chesar}# Вывод в консольprint('=' * 5, 'Заказ', '=' * 5)print('Клиент:', order.client)print('Дата заказа:', order.date)print('Блюда в заказе:')for i, v in enumerate(order.dish, start=1):    print(f'{i}. {v}')    for prod in name_dish.get(v).in_dish:        print(' --', prod[0])print('Общая калорийность: ', order.cal)print('Итоговая цена: ', order.total_price())